package org.apache.commons.math.stat.correlation;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.distribution.TDistribution;
import org.apache.commons.math.distribution.TDistributionImpl;
import org.apache.commons.math.linear.BlockRealMatrix;
import org.apache.commons.math.linear.MatrixUtils;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.stat.regression.SimpleRegression;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class PearsonsCorrelation_getCorrelationStandardErrors_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetCorrelationStandardErrorsWithSimpleData() {
        // Data with 4 observations and 2 variables
        // Variable 1: [1, 2, 3, 4]
        // Variable 2: [2, 4, 6, 8] (Perfect correlation r=1)
        // Variable 3: [1, 0, 1, 0] (Low correlation)
        double[][] data = {
            {1.0, 2.0, 1.0},
            {2.0, 4.0, 0.0},
            {3.0, 6.0, 1.0},
            {4.0, 8.0, 0.0}
        };

        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix correlationMatrix = correlation.getCorrelationMatrix();
        RealMatrix seMatrix = correlation.getCorrelationStandardErrors();

        int nVars = correlationMatrix.getColumnDimension();
        int nObs = data.length;

        Assert.assertEquals(nVars, seMatrix.getRowDimension());
        Assert.assertEquals(nVars, seMatrix.getColumnDimension());

        for (int i = 0; i < nVars; i++) {
            for (int j = 0; j < nVars; j++) {
                double r = correlationMatrix.getEntry(i, j);
                double expectedSE = Math.sqrt((1 - r * r) / (nObs - 2));
                Assert.assertEquals("SE mismatch at [" + i + "][" + j + "]", 
                    expectedSE, seMatrix.getEntry(i, j), EPSILON);
            }
        }
    }




}

package org.apache.commons.math.stat.correlation;

import java.io.*;
